function spark(tl){const ks=Object.keys(tl).sort(); if(ks.length<2) return ""; const vals=ks.map(k=>tl[k]); const mx=Math.max(...vals); const W=320,H=46; const pts=ks.map((k,i)=>`${(i/(ks.length-1))*W},${H-2-(tl[k]/mx)*(H-6)}`).join(" ");
  return `<svg class="spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><polyline fill="none" stroke="${css("--cyan")}" stroke-width="1.5" points="${pts}"/></svg><div class="muted" style="display:flex;justify-content:space-between;font-size:11px"><span>${ks[0]}</span><span>dates cited alongside the name</span><span>${ks[ks.length-1]}</span></div>`;}
function renderPanel(id){ const P=$("#panel"); if(!id){P.hidden=true;return;} const n=byId.get(id), e=ENT[id]||{cit:[],tl:{}};
  const neigh=graph.neighbors(id).map(m=>[m,graph.getEdgeAttribute(graph.edge(id,m),"w")]).sort((a,b)=>b[1]-a[1]).slice(0,14);
  const spec=graph.neighbors(id).map(m=>{const a=graph.getEdgeAttributes(graph.edge(id,m)); return [m,a.w,a.l];}).filter(x=>x[1]>=3).sort((a,b)=>sc(b[1],b[2])-sc(a[1],a[2])).slice(0,8);
  const mxp=Math.max(1,...n.pe.map(x=>x[1]));
  P.innerHTML=`<button class="close" aria-label="Close">×</button><h3>${n.label}</h3><span class="badge" style="--c:var(--${roleOf(n)})">${ROLE_LABEL[roleOf(n)]}</span>${n.vis?"":' <span class="muted">name withheld by policy</span>'}
  <div class="kv"><div><b>${fmt(n.docs)}</b><span>filings</span></div><div><b>${n.procs}</b><span>proceedings</span></div><div><b>${fmt(n.mentions)}</b><span>mentions</span></div></div>
  <div class="kv m" title="Metrics of the full graph. Bridges: betweenness (×1000). Influence: PageRank (×1000). Clustering: how much a node's neighbours link to one another. Outside the cluster: share of the links that leave the community."><div><b>${n.bt??0}</b><span>bridges</span></div><div><b>${n.pr??0}</b><span>influence</span></div><div><b>${n.cc??0}</b><span>clustering</span></div><div><b>${Math.round((n.br||0)*100)}%</b><span>outside cluster</span></div><div><b>${n.jud||0}</b><span>in rulings</span></div></div>
  <div class="period">${n.m0?`Dates cited alongside the name: ${n.m0} to ${n.m1}`:""}${n.c>=0?`${n.m0?" · ":""}cluster <b style="color:${COMM[n.c%COMM.length]}">${esc(commName(n.c))}</b>`:""}</div>
  <div class="acts">${wkBy.has(id)?`<button class="btn small" data-wiki="${id}">Profile</button>`:""}<button class="btn small" data-mm="${id}">Mind map</button><button class="btn small" data-focus="${id}">Neighbourhood only</button><button class="btn ghost small" data-hide="${id}">Hide node</button></div>
  <h4>Presence by proceeding</h4><div class="bars">${n.pe.slice(0,8).map(([p,c])=>`<div class="bar"><span>${p}</span><i style="width:${(c/mxp)*100}%"></i><span>${c}</span></div>`).join("")}</div>
  <h4>Appears alongside</h4><div class="neigh">${neigh.map(([m,w])=>`<button data-go="${m}" style="--c:var(--${roleOf(byId.get(m))})"><i></i>${byId.get(m).label}<span class="muted">${w}</span></button>`).join("")}</div>
  <h4 title="Neighbours with at least 3 filings in common, ranked by filings in common × log of specificity (lift)">Most specific links</h4><div class="neigh">${spec.map(([m,w,l])=>`<button data-go="${m}" style="--c:var(--${roleOf(byId.get(m))})" title="${w} filings in common · ${l}× the expected"><i></i>${byId.get(m).label}<span class="l">${l>=10?Math.round(l):l}×</span></button>`).join("")||"<span class='muted'>none with 3+ filings in common</span>"}</div>
  ${tpBars(e.tp)}
  ${spark(e.tl||{})}
  <h4>Where to check</h4><table><tr><th>proceeding</th><th>seq</th><th>filing</th><th>p.</th></tr>${(e.cit||[]).slice(0,12).map(([p,s,t,pg,c])=>`<tr><td>${p}</td><td>${String(s).padStart(5,"0")}</td><td>${tipo(t)}</td><td>${pg}</td></tr>`).join("")}</table>
  <p class="src">"seq" is the number that begins the file name inside the proceeding's folder in the <a href="${STF}" target="_blank" rel="noopener">STF's public package</a>. Co-occurrence on the same page does not prove a relationship; it is a starting point for reading.</p>`;
  P.hidden=false; $(".close",P).onclick=()=>select(null); $$("[data-go]",P).forEach(b=>b.onclick=()=>{ensureVisible(b.dataset.go); select(b.dataset.go);}); const wb=$("[data-wiki]",P); if(wb) wb.onclick=()=>openWiki(id); $("[data-mm]",P).onclick=()=>{ mmCenter(id); location.hash="mapa"; }; $("[data-hide]",P).onclick=()=>hideNode(id); $("[data-focus]",P).onclick=()=>{ F.focus=true; $("#focusMode").checked=true; refresh(); focus(id,.3); };
}
function syncChips(){$$("#roleChips .chip").forEach(c=>c.classList.toggle("on",F.roles.has(c.dataset.role)));}
$$("#roleChips .chip").forEach(c=>c.onclick=()=>{const r=c.dataset.role; F.roles.has(r)?F.roles.delete(r):F.roles.add(r); syncChips(); refresh();});
