const strongest=(id,role)=>graph.neighbors(id).map(m=>[m,graph.getEdgeAttribute(graph.edge(id,m),"w")]).filter(([m])=>byId.get(m).papel===role).sort((a,b)=>b[1]-a[1])[0];
const STEPS=[
 {t:"The archive in 30 seconds",b:`On 10 September 2026 the reporting justice, <strong>André Mendonça</strong>, lifted the seal on Petition 15.556 and on fourteen proceedings tied to <strong>Operation Compliance Zero</strong>, at the request of the Court's presidency. The next day the Court published everything: <strong>${fmt(META.corpus.pdfs)} filings</strong>, <strong>${fmt(META.corpus.paginas)} pages</strong>. Nobody reads that in full. This site pulls out of the text who appears, in which role and alongside whom, and sends every statement back to the page it came from.`,
  tip:"What this site is: a sourced index of relationships. What it is not: a copy of the documents, a list of taxpayer numbers, or a conclusion about anyone's guilt.",widget:"caso"},
 {t:"Fifteen proceedings, one case",b:`The material is not a single case file. It is a set of inquiries (INQ), petitions (PET) and one constitutional complaint (RCL) that cite one another. The volumes are wildly uneven: <strong>${biggestProc.processo}</strong> alone runs to ${fmt(biggestProc.pages)} pages, almost all of it DVD media with the records of federal lawsuits attached as evidence. In the map below, the size of the circle is the page count. Click a proceeding to see who dominates each one.`,
  tip:"Volume is not importance. The decisive filing in a case can be five pages long.",widget:"caso"},
 {t:"Who is who: four roles",b:`Each node gets a role inferred from the text itself. <strong>Company</strong>: a corporate term in the name. <strong>Official</strong>: a public office in context, or a signature on every page of a long filing. <strong>Lawyer</strong>: sender of the e-filing receipt, or a bar registration next to the name. <strong>Person</strong>: everyone else. Lawyers are hidden by default: they co-sign the same petitions and form dense blocks that only say "they work at the same firm".`,
  tip:"Switch on the Lawyers filter in the graph bar to watch the dense block appear. Then switch it off.",widget:"graph",setup(){F.roles=new Set(["pessoa","empresa","autoridade"]);F.minDocs=4;F.proc="";syncChips();select(null);refresh();renderer&&renderer.getCamera().animatedReset({duration:400});}},
 {t:"The centre of the graph",b:`The node with the most weighted connections among people is <strong>${centerPessoa.label}</strong>: ${centerPessoa.procs} of the 15 proceedings, ${fmt(centerPessoa.docs)} narrative filings. The panel alongside lists who shares pages with that name most often. The closest company is <strong>${byId.get(strongest(centerPessoa.id,"empresa")[0]).label}</strong>, with ${strongest(centerPessoa.id,"empresa")[1]} filings in common.`,
  tip:"Hover over any node to light up only its neighbourhood. Click to switch the panel.",widget:"graph",setup(){F.roles=new Set(["pessoa","empresa","autoridade"]);F.minDocs=3;syncChips();select(centerPessoa.id);}},
 {t:"Follow the companies",b:`Filtering down to companies reveals the corporate backbone of the case: banks, asset managers, holding companies and investment vehicles that recur across different proceedings. A company present in many proceedings is a thread to pull. In all, <strong>${empresas5}</strong> companies appear in five or more proceedings.`,
  tip:"Recurrence across proceedings is a signal. Volume inside a single proceeding is, almost always, just a large exhibit.",widget:"graph",setup(){F.roles=new Set(["empresa"]);F.minDocs=3;syncChips();select(null);refresh();renderer&&renderer.getCamera().animatedReset({duration:400});}},
 {t:"Path between two names",b:`The classic investigative question: <em>what links A to B?</em> The graph answers with the shortest path. Path mode is already armed with <strong>${centerPessoa.label}</strong> as A. Click <strong>${secondCluster.label}</strong>, who sits in another cluster, to see the bridges.`,
  tip:"The intermediate nodes of a path are the ones worth reading a filing for.",widget:"graph",setup(){F.roles=new Set(["pessoa","empresa","autoridade"]);F.minDocs=2;syncChips();select(null);setPathMode(true,centerPessoa.id);focus(secondCluster.id,.35);}},
 {t:"The mind map",b:`When the whole graph is too much, the mind map starts from one name and opens its links by category, branch by branch. Below, <strong>${topEmpresa.label}</strong> sits at the centre. Click any branch to recentre on it and follow the thread; the earlier ones stay behind as a breadcrumb trail.`,
  tip:"Use the map for a linear inquiry: from whom to whom. Use the graph to see the shape of the whole.",widget:"mm",setup(){mm.mode="entidade";mm.center=topEmpresa.id;mm.crumbs=[];}},
 {t:"Read the source; now it is over to you",b:`Nothing here is a conclusion. Every profile has a "Where to check" table with <strong>proceeding, seq and page</strong>. The <em>seq</em> is the filing's sequence number within the proceeding, and it is the beginning of the file name in the matching folder of the STF's public package. Suggestions to start with: who are the bridges between clusters? Which company appears in proceedings that do not cite each other? Which officials sign filings in more than one proceeding?`,
  tip:"Found an identification or role error? Open an issue in the repository. The policy is to fix it fast.",widget:"graph",setup(){F.roles=new Set(["pessoa","empresa","autoridade"]);F.minDocs=3;syncChips();setPathMode(false);select(topEmpresa.id);},done:true}
];
let T={cur:0,done:[]}; try{T={...T,...JSON.parse(localStorage.getItem("bmdb.tour")||"{}")}}catch(e){}
function saveT(){try{localStorage.setItem("bmdb.tour",JSON.stringify(T))}catch(e){}}
function renderRail(){$("#railSteps").innerHTML=STEPS.map((s,i)=>`<li class="${i===T.cur?"cur":""} ${T.done.includes(i)?"done":""}" data-i="${i}"><span class="n">${T.done.includes(i)?"✓":i+1}</span>${s.t}</li>`).join(""); $$("#railSteps li").forEach(li=>li.onclick=()=>{T.cur=+li.dataset.i;saveT();renderStep();});}
function parkGraph(){ const gw=$(".graph-wrap"); if(gw&&gw.parentElement!==$("#v-grafo")) $("#v-grafo").appendChild(gw); const mw=$(".mm-wrap"); if(mw&&mw.parentElement!==$("#v-mapa")&&!$("#mmToggle").checked) $("#v-mapa").appendChild(mw); }
function renderStep(){ const i=T.cur, s=STEPS[i]; if(!T.done.includes(i)){T.done.push(i);saveT();} renderRail(); $("#stepNum").textContent=`Step ${i+1} of ${STEPS.length}`; $("#stepTitle").textContent=s.t; $("#stepBody").innerHTML=s.b; $("#stepTip").textContent=s.tip||"";
  const W=$("#stepWidget"); parkGraph(); W.innerHTML="";
  if(s.widget==="graph"){ const holder=document.createElement("div"); holder.className="mini"; W.appendChild(holder); mountGraph($(".graph-wrap"),holder); setTimeout(()=>{renderer.refresh(); s.setup&&s.setup();},80); }
  else if(s.widget==="mm"||s.widget==="caso"){ const holder=document.createElement("div"); holder.className="mini"; W.appendChild(holder); holder.appendChild($(".mm-wrap")); if(s.widget==="caso"){mm.mode="caso";} else s.setup&&s.setup(); mm.vb=null; setTimeout(drawMM,50); }
  $("#prevStep").disabled=i===0; $("#nextStep").textContent=i===STEPS.length-1?"Go to the graph →":"Next →";
}
$("#prevStep").onclick=()=>{T.cur=Math.max(0,T.cur-1);saveT();renderStep();};
$("#nextStep").onclick=()=>{ if(T.cur===STEPS.length-1){location.hash="grafo";return;} T.cur++; saveT(); renderStep(); };
$("#resetTrail").onclick=()=>{T={cur:0,done:[]};saveT();renderStep();};
addEventListener("hashchange",()=>{ if(location.hash.slice(1)!=="tour") parkGraph(); if(location.hash.slice(1)!=="grafo"&&$("#mmToggle").checked){ $("#mmToggle").checked=false; $("#v-grafo").classList.remove("mm-in-graph"); $("#v-mapa").appendChild($(".mm-wrap")); } });

