      <div class="kv" style="max-width:420px"><div><b>${fmt(p.docs)}</b><span>filings</span></div><div><b>${p.procs}</b><span>proceedings</span></div><div><b>${fmt(p.mentions)}</b><span>mentions</span></div></div>
